use crate::aap::caps::state_read;

struct Node;

/// Keys tried in order. The first one that yields at least one URL wins.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

/// Parse a JSON array of strings, such as `["a", "b"]`.
/// Returns None if the text is not a well-formed array of strings.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let mut chars = s.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' => break,
            ',' => continue,
            '"' => {
                let mut cur = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            '"' => cur.push('"'),
                            '\\' => cur.push('\\'),
                            '/' => cur.push('/'),
                            'n' => cur.push('\n'),
                            't' => cur.push('\t'),
                            'r' => cur.push('\r'),
                            'b' => cur.push('\u{8}'),
                            'f' => cur.push('\u{c}'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                cur.push(char::from_u32(code).unwrap_or('\u{fffd}'));
                            }
                            _ => return None,
                        },
                        c => cur.push(c),
                    }
                }
                out.push(cur);
            }
            _ => return None,
        }
    }
    Some(out)
}

/// Turn a stored value into a list of URLs.
///
/// A value that starts with `[` is read as a JSON array of strings. Any other
/// value is split on newlines and commas. Blank entries are dropped, as are
/// lines that start with `#`. Repeated URLs are kept once, in first-seen order.
fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') {
        match parse_json_string_array(trimmed) {
            Some(v) => v,
            None => Vec::new(),
        }
    } else {
        trimmed
            .split(|c| c == '\n' || c == ',')
            .map(|s| s.to_string())
            .collect()
    };

    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() || u.starts_with('#') {
            continue;
        }
        if !urls.iter().any(|existing| existing == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // The contract requires `urls` to be present. With no subscriptions
        // stored, failing the run is better than emitting an empty list.
        panic!("no subscriptions found in state store 'subscriptions'");
    }
}

export!(Node);
